from copy import deepcopy
from random import Random
from solution import schedule

cases = [
    ({}, {\"waves\": [], \"blocked\": []}),
    (
        {\"c\": [\"a\", \"a\", \"b\"], \"b\": [], \"e\": [\"d\"], \"a\": [], \"d\": [\"c\"]},
        {\"waves\": [[\"a\", \"b\"], [\"c\"], [\"d\"], [\"e\"]], \"blocked\": []},
    ),
    (
        {\"z\": [\"z\"], \"c\": [\"b\"], \"b\": [\"a\"], \"a\": [\"b\"], \"x\": [], \"y\": [\"x\"]},
        {\"waves\": [[\"x\"], [\"y\"]], \"blocked\": [\"a\", \"b\", \"c\", \"z\"]},
    ),
    (
        {\"a\": [\"a\", \"z\", \"m\", \"z\"], \"b\": [\"m\"]},
        {\"missing\": [\"m\", \"z\"]},
    ),
]
for jobs, expected in cases:
    original = deepcopy(jobs)
    assert schedule(jobs) == expected
    assert jobs == original

def reference(jobs):
    pending = {job: set(dependencies) for job, dependencies in jobs.items()}
    missing = set().union(*pending.values()) - jobs.keys()
    if missing:
        return {\"missing\": sorted(missing)}
    waves = []
    while pending:
        wave = sorted(job for job in pending if not pending[job])
        if not wave:
            break
        waves.append(wave)
        for job in wave:
            del pending[job]
        for dependencies in pending.values():
            dependencies.difference_update(wave)
    return {\"waves\": waves, \"blocked\": sorted(pending)}

rng = Random(0)
for _ in range(500):
    names = [str(i) for i in range(rng.randrange(20))]
    jobs = {
        job: rng.choices([*names, \"unknown\"], k=rng.randrange(5))
        for job in names
    }
    assert schedule(jobs) == reference(jobs), jobs

names = [str(i) for i in range(12000)]
jobs = {name: [names[i - 1]] if i else [] for i, name in enumerate(names)}
assert schedule(jobs) == {\"waves\": [[name] for name in names], \"blocked\": []}
print(\"Passed edge cases, 500 random graphs, and a chain of 12,000 jobs.\")
